import { useState } from "react";
import { Image, ListOrdered, Swords, HeartPulse, Users, BookOpenText, Map, Wand2 } from "lucide-react";
import IconReference from "./reference/IconReference";
import RoundActionsRef from "./reference/RoundActionsRef";
import CombatMagicRef from "./reference/CombatMagicRef";
import StatusEffectsRef from "./reference/StatusEffectsRef";
import NpcPostGameRef from "./reference/NpcPostGameRef";
import AdventurerActionsRef from "./reference/AdventurerActionsRef";
import TerrainPartyRef from "./reference/TerrainPartyRef";
import SkillsMagicRef from "./reference/SkillsMagicRef";

const SUB_TABS = [
    { id: "icons",      label: "아이콘",         icon: Image },
    { id: "round",      label: "라운드·행동",    icon: ListOrdered },
    { id: "combat",     label: "전투·마법",      icon: Swords },
    { id: "status",     label: "상태 이상",      icon: HeartPulse },
    { id: "npc",        label: "NPC·사후",       icon: Users },
    { id: "adventurer", label: "행동·기술·마법", icon: BookOpenText },
    { id: "terrain",    label: "지형·파티",      icon: Map },
    { id: "skillmagic", label: "스킬·마법 사전", icon: Wand2 },
];

export default function ReferenceManager() {
    const [tab, setTab] = useState("icons");

    return (
        <div className="flex flex-col gap-4">
            {/* 서브탭 바 */}
            <div className="sticky top-14 z-20 sm:static">
                <div className="inline-flex w-full flex-wrap gap-1 rounded-xl bg-white/[0.03] p-1 ring-1 ring-white/10 sm:w-auto">
                    {SUB_TABS.map(t => {
                        const Icon = t.icon;
                        const active = t.id === tab;
                        return (
                            <button
                                key={t.id}
                                type="button"
                                onClick={() => setTab(t.id)}
                                className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                                    active
                                        ? "bg-gradient-to-r from-rose-500/80 to-fuchsia-500/80 text-white shadow"
                                        : "text-slate-300 hover:bg-white/5"
                                }`}
                            >
                                <Icon className="w-3.5 h-3.5" />
                                {t.label}
                            </button>
                        );
                    })}
                </div>
            </div>

            {/* 내용 */}
            {tab === "icons"      && <IconReference />}
            {tab === "round"      && <RoundActionsRef />}
            {tab === "combat"     && <CombatMagicRef />}
            {tab === "status"     && <StatusEffectsRef />}
            {tab === "npc"        && <NpcPostGameRef />}
            {tab === "adventurer" && <AdventurerActionsRef />}
            {tab === "terrain"    && <TerrainPartyRef />}
            {tab === "skillmagic" && <SkillsMagicRef />}

            {/* 출처 각주 */}
            <p className="text-[11px] text-slate-500 text-center leading-relaxed">
                자료 출처: 룰북 한글화 작업본 <code className="text-slate-400">doc/rulebook/0, 3, 4, 6, 7</code>
            </p>
        </div>
    );
}
