import { useEffect, useMemo, useState } from "react";
import { Search } from "lucide-react";
import { fetchMd, getCachedMd, parseBlocks, renderBlocks } from "./MarkdownRef";

// MD 본문을 '## H2' 섹션 단위(그 하위 ### 포함)로 쪼개 검색 가능하게 렌더.
// path 하나 당 섹션 목록 + 검색 필터
export default function SectionedMarkdownRef({ path }) {
    const [text, setText] = useState(getCachedMd(path));
    const [error, setError] = useState(null);
    const [query, setQuery] = useState("");

    useEffect(() => {
        let cancelled = false;
        fetchMd(path)
            .then(t => { if (!cancelled) setText(t); })
            .catch(e => { if (!cancelled) setError(e.message); });
        return () => { cancelled = true; };
    }, [path]);

    const sections = useMemo(() => splitSections(text), [text]);

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        if (!q) return sections;
        return sections.filter(s =>
            s.title.toLowerCase().includes(q) ||
            s.body.toLowerCase().includes(q)
        );
    }, [sections, query]);

    if (error) {
        return (
            <div className="rounded-xl border border-rose-400/30 bg-rose-500/10 px-4 py-3 text-sm text-rose-200">
                문서를 불러오지 못했습니다: {error}
            </div>
        );
    }
    if (!text) {
        return (
            <div className="rounded-xl border border-white/10 bg-white/[0.02] px-4 py-8 text-center text-sm text-slate-500">
                문서 로딩 중...
            </div>
        );
    }

    return (
        <div className="flex flex-col gap-4">
            {/* 검색 바 */}
            <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3 sm:p-4">
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input
                        type="text"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        placeholder="섹션 제목·본문 검색..."
                        className="w-full rounded-lg bg-black/30 pl-10 pr-3 py-2 text-sm text-white placeholder:text-slate-500 ring-1 ring-white/10 outline-none focus:ring-rose-400/40"
                    />
                </div>
                <div className="mt-2 text-[11px] text-slate-500">
                    {query
                        ? `${filtered.length} / ${sections.length}개 섹션 일치`
                        : `${sections.length}개 섹션`}
                </div>
            </div>

            {/* 섹션 목록 */}
            {filtered.length === 0 ? (
                <div className="rounded-xl border border-dashed border-white/10 bg-white/[0.02] px-4 py-8 text-center text-sm text-slate-400">
                    조건에 맞는 섹션이 없습니다.
                </div>
            ) : (
                filtered.map((s, i) => (
                    <SectionCard key={s.key} section={s} query={query} />
                ))
            )}
        </div>
    );
}

function SectionCard({ section }) {
    const blocks = useMemo(() => parseBlocks(section.body), [section.body]);
    return (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 sm:p-5">
            <h2 className="text-lg font-bold text-rose-200 mb-3 pb-1.5 border-b border-rose-400/20">
                {section.title}
            </h2>
            {renderBlocks(blocks)}
        </div>
    );
}

// H2를 섹션 경계로 하여 분할 (각 섹션은 하위 ### 포함 전체 본문)
function splitSections(md) {
    if (!md) return [];
    const lines = md.split(/\r?\n/);
    const sections = [];
    let current = null;
    let key = 0;

    for (const line of lines) {
        const h2 = line.match(/^##\s+(.*)$/);
        const h1 = line.match(/^#\s+(.*)$/);
        if (h2) {
            if (current) sections.push(current);
            current = {
                key: `s${key++}`,
                title: h2[1].trim(),
                bodyLines: [],
            };
            continue;
        }
        if (h1) {
            // 최상위 H1은 skip (파일 제목)
            continue;
        }
        if (current) current.bodyLines.push(line);
    }
    if (current) sections.push(current);

    // body 문자열화
    return sections.map(s => ({
        key: s.key,
        title: s.title,
        body: s.bodyLines.join("\n"),
    }));
}
