import { useMemo, useState } from "react";
import { Search, Users, Wand2, Swords, Sparkles } from "lucide-react";
import { CLASSES, SKILLS, SPELLS, SPELL_SCHOOLS } from "../../resource/dataSet/skillsMagic";

const CATEGORY_TABS = [
    { id: "all",     label: "전체",   icon: Sparkles },
    { id: "class",   label: "클래스", icon: Users },
    { id: "skill",   label: "기술",   icon: Swords },
    { id: "spell",   label: "주문",   icon: Wand2 },
];

const SCHOOL_IDS = ["proximate", "vicarious", "elemental", "forbidden"];

export default function SkillsMagicRef() {
    const [category, setCategory] = useState("all");
    const [schools, setSchools] = useState(new Set(SCHOOL_IDS));
    const [query, setQuery] = useState("");

    // 통합 엔트리 생성
    const allEntries = useMemo(() => {
        const out = [];
        for (const c of CLASSES) {
            out.push({
                kind: "class",
                id: `c-${c.id}`,
                ko: c.ko, en: c.en,
                sub: c.family,
                hay: [c.ko, c.en, c.family, c.role, (c.tracks || []).join(" ")].join(" ").toLowerCase(),
                data: c,
            });
        }
        for (const s of SKILLS) {
            const levelText = s.levels.map(l => `${l.ko} ${l.en} ${l.kind} ${l.text}`).join(" ");
            out.push({
                kind: "skill",
                id: `s-${s.id}`,
                ko: s.ko, en: s.en,
                sub: "기술 트랙",
                hay: [s.ko, s.en, s.flavor, levelText].join(" ").toLowerCase(),
                data: s,
            });
        }
        for (const sp of SPELLS) {
            out.push({
                kind: "spell",
                id: `p-${sp.id}`,
                ko: sp.ko, en: sp.en,
                sub: `${SPELL_SCHOOLS[sp.school].ko} · Lv.${sp.level}`,
                school: sp.school,
                hay: [sp.ko, sp.en, SPELL_SCHOOLS[sp.school].ko, SPELL_SCHOOLS[sp.school].en, sp.text].join(" ").toLowerCase(),
                data: sp,
            });
        }
        return out;
    }, []);

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        return allEntries.filter(e => {
            if (category !== "all" && e.kind !== category) return false;
            if (e.kind === "spell" && !schools.has(e.school)) return false;
            if (!q) return true;
            return e.hay.includes(q);
        });
    }, [allEntries, category, schools, query]);

    const counts = useMemo(() => ({
        all: allEntries.length,
        class: allEntries.filter(e => e.kind === "class").length,
        skill: allEntries.filter(e => e.kind === "skill").length,
        spell: allEntries.filter(e => e.kind === "spell").length,
    }), [allEntries]);

    const toggleSchool = (id) => {
        setSchools(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    return (
        <div className="flex flex-col gap-4">
            {/* 검색 + 카테고리 */}
            <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3 sm:p-4">
                <div className="relative mb-3">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input
                        type="text"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        placeholder="한글·영문·본문·계통 검색..."
                        className="w-full rounded-lg bg-black/30 pl-10 pr-3 py-2 text-sm text-white placeholder:text-slate-500 ring-1 ring-white/10 outline-none focus:ring-rose-400/40"
                    />
                </div>
                <div className="flex flex-wrap gap-1.5">
                    {CATEGORY_TABS.map(t => {
                        const Icon = t.icon;
                        const active = category === t.id;
                        return (
                            <button
                                key={t.id}
                                type="button"
                                onClick={() => setCategory(t.id)}
                                className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                                    active
                                        ? "bg-gradient-to-r from-rose-500 to-fuchsia-500 text-white shadow"
                                        : "bg-white/[0.04] text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08]"
                                }`}
                            >
                                <Icon className="w-3.5 h-3.5" />
                                {t.label} <span className={active ? "opacity-80" : "text-slate-500"}>({counts[t.id]})</span>
                            </button>
                        );
                    })}
                </div>

                {/* 주문 계통 필터 (주문 또는 전체 탭에서) */}
                {(category === "spell" || category === "all") && (
                    <div className="mt-3 pt-3 border-t border-white/5">
                        <div className="mb-1.5 text-[10px] uppercase tracking-widest text-slate-500">
                            주문 계통
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            {SCHOOL_IDS.map(sid => {
                                const s = SPELL_SCHOOLS[sid];
                                const on = schools.has(sid);
                                return (
                                    <button
                                        key={sid}
                                        type="button"
                                        onClick={() => toggleSchool(sid)}
                                        className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium transition-all ring-1 ${
                                            on ? s.chip : "bg-white/[0.02] text-slate-500 ring-white/10"
                                        }`}
                                        title={s.desc}
                                    >
                                        {s.ko} <span className="opacity-60">({s.color})</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}
            </div>

            <div className="text-[11px] text-slate-500 px-1">
                {filtered.length}개 결과
            </div>

            {/* 결과 리스트 */}
            {filtered.length === 0 ? (
                <div className="rounded-xl border border-dashed border-white/10 bg-white/[0.02] px-4 py-8 text-center text-sm text-slate-400">
                    조건에 맞는 항목이 없습니다.
                </div>
            ) : (
                <div className="flex flex-col gap-3">
                    {filtered.map(e => {
                        if (e.kind === "class") return <ClassCard key={e.id} c={e.data} />;
                        if (e.kind === "skill") return <SkillCard key={e.id} s={e.data} />;
                        if (e.kind === "spell") return <SpellCard key={e.id} sp={e.data} />;
                        return null;
                    })}
                </div>
            )}
        </div>
    );
}

// ---------- 카드 컴포넌트 ----------

function CardShell({ badge, badgeColor, title, subtitle, children }) {
    return (
        <article className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 sm:p-5">
            <header className="mb-3 flex items-start justify-between gap-3">
                <div className="min-w-0">
                    <div className="flex items-center gap-2 flex-wrap mb-1">
                        <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-semibold ring-1 tracking-wider uppercase ${badgeColor}`}>
                            {badge}
                        </span>
                        {subtitle && (
                            <span className="text-[11px] text-slate-400">{subtitle}</span>
                        )}
                    </div>
                    <h3 className="text-base sm:text-lg font-bold text-white">
                        {title}
                    </h3>
                </div>
            </header>
            {children}
        </article>
    );
}

function ClassCard({ c }) {
    return (
        <CardShell
            badge="CLASS"
            badgeColor="bg-emerald-500/20 text-emerald-200 ring-emerald-400/30"
            title={<>{c.ko} <span className="text-[13px] font-mono font-normal text-slate-500">({c.en})</span></>}
            subtitle={c.family}
        >
            <p className="text-[13px] leading-relaxed text-slate-300 mb-3">
                {c.role}
            </p>
            {c.tracks && c.tracks.length > 0 && (
                <div>
                    <div className="text-[10px] uppercase tracking-widest text-rose-300/70 mb-1">기술 트랙</div>
                    <div className="flex flex-wrap gap-1.5">
                        {c.tracks.map(t => (
                            <span key={t} className="inline-block rounded-md bg-white/[0.04] px-2 py-0.5 text-[11px] font-medium text-slate-200 ring-1 ring-white/10">
                                {t}
                            </span>
                        ))}
                    </div>
                </div>
            )}
        </CardShell>
    );
}

function SkillCard({ s }) {
    return (
        <CardShell
            badge="SKILL"
            badgeColor="bg-amber-500/20 text-amber-200 ring-amber-400/30"
            title={<>{s.ko} <span className="text-[13px] font-mono font-normal text-slate-500">({s.en})</span></>}
            subtitle="기술 트랙 · 3레벨"
        >
            {s.flavor && (
                <p className="italic text-[12px] text-amber-200/80 mb-3 leading-relaxed">
                    {s.flavor}
                </p>
            )}
            <div className="flex flex-col gap-2">
                {s.levels.map(l => (
                    <div key={l.lv} className="rounded-lg bg-black/20 ring-1 ring-white/5 p-3">
                        <div className="flex items-center gap-2 flex-wrap mb-1.5">
                            <span className="inline-flex items-center justify-center shrink-0 w-6 h-6 rounded-full text-[10px] font-bold bg-amber-500/25 text-amber-100 ring-1 ring-amber-400/40">
                                Lv{l.lv}
                            </span>
                            <span className="text-sm font-semibold text-white">{l.ko}</span>
                            <span className="text-[11px] font-mono text-slate-500">({l.en})</span>
                            <span className="ml-auto inline-block rounded-md bg-white/[0.03] px-2 py-0.5 text-[10px] font-medium text-rose-200/80 ring-1 ring-rose-400/20">
                                {l.kind}
                            </span>
                        </div>
                        <p className="text-[12.5px] leading-relaxed text-slate-200">
                            {l.text}
                        </p>
                    </div>
                ))}
            </div>
        </CardShell>
    );
}

function SpellCard({ sp }) {
    const school = SPELL_SCHOOLS[sp.school];
    return (
        <CardShell
            badge="SPELL"
            badgeColor="bg-fuchsia-500/20 text-fuchsia-200 ring-fuchsia-400/30"
            title={<>{sp.ko} <span className="text-[13px] font-mono font-normal text-slate-500">({sp.en})</span></>}
            subtitle={<>Lv.{sp.level} · {school.ko} ({school.color})</>}
        >
            <div className={`mb-3 inline-flex items-center rounded-full px-2.5 py-0.5 text-[11px] ring-1 ${school.chip}`}>
                {school.ko}
            </div>
            <p className="text-[13px] leading-relaxed text-slate-200 whitespace-pre-line">
                {sp.text}
            </p>
        </CardShell>
    );
}
