import { useMemo, useState } from "react";
import { Search, Tag } from "lucide-react";
import iconsData from "../../resource/dataSet/icons.json";
import { ICON_LABELS, ICON_KIND_LABELS } from "../../resource/dataSet/iconLabels.js";
import CardIcon from "../CardIcon";

function entries() {
    return Object.entries(iconsData).map(([name, def]) => {
        const label = ICON_LABELS[name] || {};
        return {
            name,
            ko: label.ko || name,
            desc: label.desc || def.notes || "",
            aliases: def.aliases || [],
            kind: def.kind || "inline",
            asset: def.asset || "",
        };
    });
}

const KIND_ORDER = ["inline", "footer", "food-panel"];

export default function IconReference() {
    const all = useMemo(entries, []);
    const [query, setQuery] = useState("");
    const [kindFilter, setKindFilter] = useState("all");

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        return all.filter(e => {
            if (kindFilter !== "all" && e.kind !== kindFilter) return false;
            if (!q) return true;
            const hay = [
                e.name,
                e.ko,
                e.desc,
                ...e.aliases,
            ].join(" ").toLowerCase();
            return hay.includes(q);
        });
    }, [all, query, kindFilter]);

    const grouped = useMemo(() => {
        const g = {};
        for (const e of filtered) {
            if (!g[e.kind]) g[e.kind] = [];
            g[e.kind].push(e);
        }
        for (const k of Object.keys(g)) {
            g[k].sort((a, b) => a.ko.localeCompare(b.ko, "ko"));
        }
        return g;
    }, [filtered]);

    const kindCounts = useMemo(() => {
        const c = { all: all.length };
        for (const e of all) c[e.kind] = (c[e.kind] || 0) + 1;
        return c;
    }, [all]);

    return (
        <div className="flex flex-col gap-4">
            {/* 검색 + 분류 필터 */}
            <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3 sm:p-4">
                <div className="relative mb-3">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input
                        type="text"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        placeholder="한글·영문·별칭·설명으로 검색..."
                        className="w-full rounded-lg bg-black/30 pl-10 pr-3 py-2 text-sm text-white placeholder:text-slate-500 ring-1 ring-white/10 outline-none focus:ring-rose-400/40"
                    />
                </div>
                <div className="flex flex-wrap gap-1.5">
                    <KindButton
                        active={kindFilter === "all"}
                        onClick={() => setKindFilter("all")}
                        label="전체"
                        count={kindCounts.all}
                    />
                    {KIND_ORDER.map(k => (
                        kindCounts[k] ? (
                            <KindButton
                                key={k}
                                active={kindFilter === k}
                                onClick={() => setKindFilter(k)}
                                label={ICON_KIND_LABELS[k]?.ko || k}
                                count={kindCounts[k]}
                            />
                        ) : null
                    ))}
                </div>
            </div>

            {/* 사용법 안내 */}
            <div className="rounded-xl border border-rose-400/20 bg-rose-500/5 px-4 py-2.5 text-xs leading-relaxed text-rose-200/80">
                카드 본문의 <code className="px-1.5 py-0.5 rounded bg-black/30 text-rose-100">[이름]</code> 토큰은
                아래 <b className="text-rose-100">본문 인라인 아이콘</b>의 이미지로 치환됩니다. 매핑 키(영문)와 별칭 모두 인식합니다.
            </div>

            {/* 분류별 섹션 */}
            {KIND_ORDER.filter(k => grouped[k]).map(k => (
                <section key={k}>
                    <div className="mb-2 flex items-baseline justify-between gap-2 px-1">
                        <h3 className="text-sm font-semibold tracking-wide text-rose-200 flex items-center gap-1.5">
                            <Tag className="w-3.5 h-3.5" /> {ICON_KIND_LABELS[k]?.ko || k}
                            <span className="text-[10px] text-slate-500 font-normal">({grouped[k].length})</span>
                        </h3>
                        {ICON_KIND_LABELS[k]?.desc && (
                            <span className="hidden sm:inline text-[11px] text-slate-500 truncate">
                                {ICON_KIND_LABELS[k].desc}
                            </span>
                        )}
                    </div>
                    <div className="grid grid-cols-1 gap-2 sm:grid-cols-2 xl:grid-cols-3">
                        {grouped[k].map(e => (
                            <IconRow key={e.name} entry={e} />
                        ))}
                    </div>
                </section>
            ))}

            {filtered.length === 0 && (
                <div className="rounded-xl border border-dashed border-white/10 bg-white/[0.02] px-4 py-8 text-center text-sm text-slate-400">
                    조건에 맞는 아이콘이 없습니다.
                </div>
            )}
        </div>
    );
}

function KindButton({ active, onClick, label, count }) {
    return (
        <button
            type="button"
            onClick={onClick}
            className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                active
                    ? "bg-gradient-to-r from-rose-500 to-fuchsia-500 text-white shadow-md"
                    : "bg-white/[0.04] text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08]"
            }`}
        >
            {label} <span className={active ? "opacity-80" : "text-slate-500"}>({count})</span>
        </button>
    );
}

function IconRow({ entry }) {
    const { name, ko, desc, aliases, kind } = entry;
    const size = kind === "food-panel" ? 56 : kind === "footer" ? 32 : 24;
    return (
        <div className="flex items-start gap-3 rounded-xl border border-white/10 bg-white/[0.02] p-3 hover:bg-white/[0.04] transition-colors">
            <div className="shrink-0 flex items-center justify-center rounded-lg bg-black/30 ring-1 ring-white/10 p-2 min-w-[52px] min-h-[52px]">
                <CardIcon name={name} size={size} />
            </div>
            <div className="min-w-0 flex-1">
                <div className="flex items-baseline justify-between gap-2">
                    <div className="min-w-0">
                        <div className="text-sm font-semibold text-white truncate">{ko}</div>
                        <div className="text-[10px] font-mono text-rose-300/70 truncate">[{name}]</div>
                    </div>
                </div>
                {desc && (
                    <p className="mt-1 text-[11px] leading-relaxed text-slate-400">
                        {desc}
                    </p>
                )}
                {aliases.length > 0 && (
                    <div className="mt-1.5 flex flex-wrap gap-1">
                        {aliases.map(a => (
                            <span
                                key={a}
                                className="inline-block rounded bg-white/[0.04] px-1.5 py-0.5 text-[9px] font-mono text-slate-500"
                            >
                                {a}
                            </span>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}
