import { useEffect, useMemo, useState } from "react";
import {
    Shuffle, Undo2, Play, Layers, ChevronDown, ChevronUp, Tag,
    Trash2, Bookmark, Sparkles, RotateCcw, FastForward, Zap, X, Eye,
} from "lucide-react";
import { maladumSets } from "../resource/dataSet/setMeta";
import { allCards, shuffleCards, DREAD_BANDS } from "../util/cardCatalog";
import CardView from "./CardView";

const TYPE_KO_MAP = {
    Environment: "환경",
    Revenant: "레븐넌트",
    Dungeon: "던전",
    Denizen: "주민",
    Novice: "초보",
    Veteran: "베테랑",
    Corrupter: "타락자",
    "Wandering Beast": "유랑 야수",
    Malagaunt: "말라건트",
};

function splitTypes(type) {
    return String(type || "").split(/[+/,]/).map(s => s.trim()).filter(Boolean);
}

const STORAGE_KEY = "maladum-deck-sim-v1";

function loadStoredState() {
    if (typeof window === "undefined") return null;
    try {
        const raw = window.localStorage.getItem(STORAGE_KEY);
        if (!raw) return null;
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

function saveStoredState(obj) {
    if (typeof window === "undefined") return;
    try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(obj));
    } catch {
        // storage full / disabled — silently ignore
    }
}

// 자동 폐기 룰을 적용하며 덱에서 다음 유효 카드를 찾는다.
// autoDiscardVeteran=true면 Veteran 유형은 자동으로 폐기더미로 보낸다.
function pickNextRespectingAutoDiscard(deck, autoDiscardVeteran) {
    const autoDiscarded = [];
    let remaining = deck;
    let picked = null;
    while (remaining.length > 0) {
        const [next, ...rest] = remaining;
        if (autoDiscardVeteran && splitTypes(next.type).includes("Veteran")) {
            autoDiscarded.push(next);
            remaining = rest;
            continue;
        }
        picked = next;
        remaining = rest;
        break;
    }
    return { picked, remaining, autoDiscarded };
}

// 유형별 요청 수량(remain)에 맞춰, 복합 유형 카드가 여러 수요를 동시 충족하도록 그리디로 덱 구성.
// 반환: { selected: 셔플된 덱, unused: 덱에 들어가지 않은 미사용 풀 }
function buildDeckFromCounts(pool, counts) {
    const remain = { ...counts };
    const selected = [];
    const unused = [];
    const shuffled = shuffleCards(pool);
    for (const card of shuffled) {
        const parts = splitTypes(card.type);
        const useful = parts.filter(p => (remain[p] || 0) > 0);
        if (useful.length === 0) {
            unused.push(card);
            continue;
        }
        selected.push(card);
        for (const p of useful) remain[p]--;
    }
    return { selected: shuffleCards(selected), unused };
}

const BAND_CLASS = [
    "from-emerald-500 to-emerald-600",
    "from-yellow-500 to-yellow-600",
    "from-orange-500 to-orange-600",
    "from-rose-500 to-rose-600",
    "from-red-600 to-red-700",
    "from-fuchsia-600 to-purple-700",
];

export default function DeckSimulator() {
    const defaultSets = useMemo(() => new Set(maladumSets.map(s => s.id)), []);
    const stored = useMemo(loadStoredState, []);

    const [includedSets, setIncludedSets] = useState(() =>
        Array.isArray(stored?.includedSets) ? new Set(stored.includedSets) : defaultSets
    );
    const [typeCounts, setTypeCounts] = useState(() => stored?.typeCounts || {});
    const [dreadBand, setDreadBand] = useState(() => stored?.dreadBand ?? 0);

    // 영역 모델
    const [eventDeck, setEventDeck] = useState(() => stored?.eventDeck || []);
    const [current, setCurrent] = useState(() => stored?.current || null);
    const [discardPile, setDiscardPile] = useState(() => stored?.discardPile || []);
    const [activePlay, setActivePlay] = useState(() => stored?.activePlay || []);
    const [unusedPool, setUnusedPool] = useState(() => stored?.unusedPool || []);
    const [history, setHistory] = useState(() => stored?.history || []);
    const [autoDiscardVeteran, setAutoDiscardVeteran] = useState(() => !!stored?.autoDiscardVeteran);

    const [configOpen, setConfigOpen] = useState(false);
    const [viewingCard, setViewingCard] = useState(null);      // 상세보기 모달
    const [discardListOpen, setDiscardListOpen] = useState(false); // 버린 더미 목록 펼침

    const typeMax = useMemo(() => {
        const m = {};
        for (const c of allCards()) {
            if (!includedSets.has(c.setId)) continue;
            for (const t of splitTypes(c.type)) {
                m[t] = (m[t] || 0) + 1;
            }
        }
        return m;
    }, [includedSets]);

    const typeList = useMemo(() => Object.keys(typeMax).sort(), [typeMax]);

    useEffect(() => {
        setTypeCounts(prev => {
            const next = {};
            for (const [t, max] of Object.entries(typeMax)) {
                next[t] = prev[t] !== undefined ? Math.min(prev[t], max) : max;
            }
            return next;
        });
    }, [typeMax]);

    // 모든 주요 상태를 localStorage에 자동 저장 (셔플 & 뽑기 이후 세션 보존)
    useEffect(() => {
        saveStoredState({
            includedSets: Array.from(includedSets),
            typeCounts,
            dreadBand,
            eventDeck,
            current,
            discardPile,
            activePlay,
            unusedPool,
            history,
            autoDiscardVeteran,
        });
    }, [
        includedSets, typeCounts, dreadBand,
        eventDeck, current, discardPile, activePlay, unusedPool, history,
        autoDiscardVeteran,
    ]);

    const targetDeckSize = useMemo(
        () => Object.values(typeCounts).reduce((s, n) => s + (n || 0), 0),
        [typeCounts]
    );

    const cardPool = useMemo(() => {
        return allCards().filter(c => includedSets.has(c.setId));
    }, [includedSets]);

    const remainingInDeck = eventDeck.length;
    const totalKnown = eventDeck.length + (current ? 1 : 0) + discardPile.length + activePlay.length;
    const isSessionActive = totalKnown > 0 || unusedPool.length > 0;

    const resetAllZones = () => {
        setEventDeck([]);
        setCurrent(null);
        setDiscardPile([]);
        setActivePlay([]);
        setUnusedPool([]);
        setHistory([]);
    };

    const handleToggleSet = (setId) => {
        setIncludedSets(prev => {
            const next = new Set(prev);
            if (next.has(setId)) next.delete(setId);
            else next.add(setId);
            return next;
        });
        resetAllZones();
    };

    const setTypeCountDirect = (type, value) => {
        const max = typeMax[type] || 0;
        const safe = Number.isFinite(value) ? value : 0;
        const clamped = Math.max(0, Math.min(max, Math.floor(safe)));
        setTypeCounts(prev => {
            if ((prev[type] || 0) === clamped) return prev;
            return { ...prev, [type]: clamped };
        });
        resetAllZones();
    };

    const setAllMax = () => {
        setTypeCounts(() => ({ ...typeMax }));
        resetAllZones();
    };

    const setAllZero = () => {
        const z = {};
        for (const t of typeList) z[t] = 0;
        setTypeCounts(z);
        resetAllZones();
    };

    // 새 덱 구성 + 첫 카드 공개 (current). 선택되지 않은 카드는 unusedPool로.
    const buildAndDraw = () => {
        if (cardPool.length === 0 || targetDeckSize === 0) return;
        const { selected, unused } = buildDeckFromCounts(cardPool, typeCounts);
        if (selected.length === 0) return;
        const { picked, remaining, autoDiscarded } = pickNextRespectingAutoDiscard(selected, autoDiscardVeteran);
        setEventDeck(remaining);
        setCurrent(picked);
        setDiscardPile(autoDiscarded);
        setActivePlay([]);
        setUnusedPool(unused);
        setHistory([]);
    };

    // 세션 진행 중이면 소프트 리셔플(남은 덱 + 버린 더미만 섞음, 유지/미사용/현재 보존).
    // 세션 시작 전이면 처음부터 빌드.
    const handleReshuffle = () => {
        if (!isSessionActive) {
            buildAndDraw();
            return;
        }
        const toReshuffle = [...eventDeck, ...discardPile];
        if (toReshuffle.length === 0) return;
        setEventDeck(shuffleCards(toReshuffle));
        setDiscardPile([]);
    };

    const handleDraw = () => {
        if (cardPool.length === 0 || targetDeckSize === 0) return;
        if (current) return; // 현재 카드 처리 전엔 뽑기 금지
        if (!isSessionActive) {
            buildAndDraw();
            return;
        }
        if (eventDeck.length === 0) return; // 덱 소진
        const { picked, remaining, autoDiscarded } = pickNextRespectingAutoDiscard(eventDeck, autoDiscardVeteran);
        setEventDeck(remaining);
        if (autoDiscarded.length > 0) {
            setDiscardPile(prev => [...prev, ...autoDiscarded]);
        }
        if (picked) setCurrent(picked);
    };

    // 연쇄 드로우: 특정 유형 카드가 나올 때까지 계속 뽑고, 중간 카드는 모두 버린다.
    // 나온 카드는 current로. 끝까지 못 찾으면 덱 소진.
    const chainDrawUntil = (targetType) => {
        if (current || eventDeck.length === 0) return;
        const discarded = [];
        let remaining = [...eventDeck];
        let found = null;
        while (remaining.length > 0) {
            const [next, ...rest] = remaining;
            remaining = rest;
            if (splitTypes(next.type).includes(targetType)) {
                found = next;
                break;
            }
            discarded.push(next);
        }
        setEventDeck(remaining);
        if (discarded.length > 0) {
            setDiscardPile(prev => [...prev, ...discarded]);
        }
        if (found) setCurrent(found);
    };

    const handleResolveCurrent = (action) => {
        if (!current) return;
        if (action === "discard") {
            setDiscardPile(prev => [...prev, current]);
        } else if (action === "shuffle") {
            setEventDeck(prev => shuffleCards([...prev, current]));
        } else if (action === "keep") {
            setActivePlay(prev => [...prev, current]);
        }
        setHistory(prev => [...prev, { card: current, action }]);
        setCurrent(null);
    };

    // activePlay 카드를 해당 index에서 꺼내 다른 영역으로 보내기
    const handleActivePlayAction = (idx, action) => {
        const card = activePlay[idx];
        if (!card) return;
        const next = activePlay.filter((_, i) => i !== idx);
        setActivePlay(next);
        if (action === "discard") {
            setDiscardPile(prev => [...prev, card]);
        } else if (action === "shuffle") {
            setEventDeck(prev => shuffleCards([...prev, card]));
        }
    };

    // 되돌리기: 현재 공개된 카드를 덱 top으로 되돌림 (#040 예지와 동일한 동작)
    const handleUndo = () => {
        if (!current) return;
        setEventDeck(prev => [current, ...prev]);
        setCurrent(null);
    };

    // 버린 더미에서 조건에 맞는 카드를 꺼내 current로.
    // mode='top'은 가장 최근 들어간 것, mode='random'은 조건 통과 중 랜덤.
    const recallFromDiscard = (predicate, mode) => {
        if (current) return;
        const matched = [];
        for (let i = 0; i < discardPile.length; i++) {
            if (predicate(discardPile[i])) matched.push(i);
        }
        if (matched.length === 0) return;
        let pickIdx;
        if (mode === "random") pickIdx = matched[Math.floor(Math.random() * matched.length)];
        else pickIdx = matched[matched.length - 1]; // top (가장 최근 버린)
        const card = discardPile[pickIdx];
        setDiscardPile(discardPile.filter((_, i) => i !== pickIdx));
        setCurrent(card);
    };

    // 버린 더미 전체를 덱에 넣고 섞기 (#065)
    const recallAllToDeck = () => {
        if (discardPile.length === 0) return;
        setEventDeck(prev => shuffleCards([...prev, ...discardPile]));
        setDiscardPile([]);
    };

    // 미사용 풀에서 유형 필터로 랜덤 1장을 뽑아 current로
    const drawFromUnused = (type) => {
        if (current) return;
        const candidates = type
            ? unusedPool.filter(c => splitTypes(c.type).includes(type))
            : unusedPool.slice();
        if (candidates.length === 0) return;
        const pick = candidates[Math.floor(Math.random() * candidates.length)];
        setUnusedPool(unusedPool.filter(c => c !== pick));
        setCurrent(pick);
    };

    // 각 영역의 "매치되는 카드" 수를 미리 계산
    const discardVeteranCount = useMemo(
        () => discardPile.filter(c => splitTypes(c.type).includes("Veteran")).length,
        [discardPile]
    );
    const discardNonVeteranCount = useMemo(
        () => discardPile.filter(c => !splitTypes(c.type).includes("Veteran")).length,
        [discardPile]
    );
    const discardRevenantCount = useMemo(
        () => discardPile.filter(c => splitTypes(c.type).includes("Revenant")).length,
        [discardPile]
    );

    // 미사용 풀의 유형별 수량
    const unusedByType = useMemo(() => {
        const m = {};
        for (const c of unusedPool) {
            for (const t of splitTypes(c.type)) {
                m[t] = (m[t] || 0) + 1;
            }
        }
        return m;
    }, [unusedPool]);
    const unusedTypeList = useMemo(() => Object.keys(unusedByType).sort(), [unusedByType]);

    const canDraw = !current && cardPool.length > 0 && targetDeckSize > 0 &&
        (!isSessionActive || eventDeck.length > 0);
    const empty = cardPool.length === 0 || targetDeckSize === 0;
    const deckEmpty = isSessionActive && !current && eventDeck.length === 0;
    const canReshuffle = !empty && (!isSessionActive || eventDeck.length + discardPile.length > 0);

    const setConfigPanel = (
        <div className="flex flex-col gap-3">
            <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                    <Layers className="w-3.5 h-3.5" /> 컨텐츠 세트
                </div>
                <div className="flex flex-col gap-1.5">
                    {maladumSets.map(s => {
                        const on = includedSets.has(s.id);
                        return (
                            <button
                                key={s.id}
                                onClick={() => handleToggleSet(s.id)}
                                className={`flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-left transition-colors ${
                                    on
                                        ? "bg-gradient-to-r " + s.accent + " text-white shadow-md"
                                        : "bg-white/[0.02] text-slate-400 hover:bg-white/[0.06]"
                                }`}
                            >
                                <span className="flex items-center gap-2 min-w-0">
                                    <span className={`shrink-0 w-3.5 h-3.5 rounded ring-1 ${on ? "bg-white/90 ring-white/80" : "bg-transparent ring-white/30"}`}>
                                        {on && <span className="block w-full h-full rounded bg-rose-500/90" />}
                                    </span>
                                    <span className="min-w-0">
                                        <span className="block text-sm font-semibold truncate">{s.name_ko}</span>
                                        <span className="block text-[10px] opacity-70 truncate">{s.name}</span>
                                    </span>
                                </span>
                                <span className={`text-xs tabular-nums ${on ? "text-white" : "text-slate-500"}`}>
                                    {s.data.cards.length}
                                </span>
                            </button>
                        );
                    })}
                </div>
            </div>

            {typeList.length > 0 && (
                <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                    <div className="mb-3 flex items-center justify-between gap-2">
                        <span className="flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                            <Tag className="w-3.5 h-3.5" /> 유형별 매수
                        </span>
                        <div className="flex items-center gap-1 text-[10px]">
                            <button
                                onClick={setAllMax}
                                className="rounded px-1.5 py-0.5 text-slate-400 hover:bg-white/[0.08] hover:text-slate-200"
                            >
                                최대
                            </button>
                            <span className="text-slate-700">·</span>
                            <button
                                onClick={setAllZero}
                                className="rounded px-1.5 py-0.5 text-slate-400 hover:bg-white/[0.08] hover:text-slate-200"
                            >
                                0
                            </button>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1.5">
                        {typeList.map(t => {
                            const count = typeCounts[t] || 0;
                            const max = typeMax[t] || 0;
                            const label = TYPE_KO_MAP[t] || t;
                            const active = count > 0;
                            return (
                                <div
                                    key={t}
                                    className={`flex items-center justify-between gap-2 rounded-lg px-2.5 py-1.5 ${
                                        active ? "bg-rose-500/10 ring-1 ring-rose-400/20" : "bg-white/[0.02]"
                                    }`}
                                >
                                    <div className="min-w-0">
                                        <div className={`text-sm font-semibold ${active ? "text-rose-100" : "text-slate-400"}`}>
                                            {label}
                                        </div>
                                        <div className="text-[10px] text-slate-500 truncate">{t}</div>
                                    </div>
                                    <div className="flex items-center gap-1.5 shrink-0">
                                        <input
                                            type="number"
                                            min={0}
                                            max={max}
                                            value={count}
                                            onChange={e => setTypeCountDirect(t, parseInt(e.target.value, 10))}
                                            onFocus={e => e.target.select()}
                                            className="w-14 rounded-md bg-white/[0.04] px-2 py-1 text-center text-sm font-bold text-white tabular-nums ring-1 ring-white/10 outline-none focus:ring-rose-400/40 [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
                                        />
                                        <span className="text-[10px] text-slate-500 tabular-nums">/{max}</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-3 pt-3 border-t border-white/5 text-[11px] text-slate-500 leading-relaxed">
                        복합 유형 카드 1장은 포함된 모든 유형의 수요를 동시에 충족합니다.<br />
                        (예: 던전+주민 카드 → 던전 1, 주민 1 동시 차감)
                    </div>
                </div>
            )}

            <div className="rounded-xl border border-white/10 bg-white/[0.02] px-4 py-2 flex items-center justify-between text-xs">
                <span className="text-slate-400">목표 덱 크기</span>
                <span className="text-white font-bold tabular-nums">
                    {targetDeckSize}장
                    {isSessionActive && totalKnown !== targetDeckSize && (
                        <span className="ml-1 text-slate-500">(실제 {totalKnown})</span>
                    )}
                </span>
            </div>

            <label className="flex items-start gap-2 rounded-xl border border-white/10 bg-white/[0.02] px-3 py-2.5 cursor-pointer hover:bg-white/[0.04]">
                <input
                    type="checkbox"
                    checked={autoDiscardVeteran}
                    onChange={e => setAutoDiscardVeteran(e.target.checked)}
                    className="mt-0.5 shrink-0 accent-rose-500"
                />
                <div className="min-w-0">
                    <div className="text-xs font-semibold text-slate-200 flex items-center gap-1.5">
                        <Zap className="w-3 h-3 text-amber-300" /> 베테랑 자동 폐기
                    </div>
                    <div className="text-[10px] text-slate-500 leading-snug mt-0.5">
                        뽑힌 Veteran 카드를 자동으로 폐기더미로 보내고 다음 카드까지 뽑음 (#049)
                    </div>
                </div>
            </label>
        </div>
    );

    return (
        <div className="flex flex-col gap-4 sm:grid sm:grid-cols-12 sm:gap-5">
            {/* 모바일 전용: 설정 토글 */}
            <div className="sm:hidden">
                <button
                    onClick={() => setConfigOpen(o => !o)}
                    className="flex w-full items-center justify-between rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5"
                >
                    <span className="flex items-center gap-2 text-sm font-semibold text-rose-200">
                        <Layers className="w-4 h-4" />
                        덱 구성 ({includedSets.size}세트 · 목표 {targetDeckSize}장)
                    </span>
                    {configOpen
                        ? <ChevronUp className="w-4 h-4 text-slate-400" />
                        : <ChevronDown className="w-4 h-4 text-slate-400" />}
                </button>
                {configOpen && <div className="mt-3">{setConfigPanel}</div>}
            </div>

            {/* 좌측: 설정 */}
            <aside className="hidden sm:block sm:col-span-3">
                {setConfigPanel}
            </aside>

            {/* 중앙: 공포 단계 + 영역 요약 + 조작 + 현재 카드 + 유지 + 이력 */}
            <section className="sm:col-span-9 flex flex-col gap-4">
                {/* 공포 단계 */}
                <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3">
                    <div className="mb-2 flex items-center justify-between gap-2">
                        <span className="text-xs tracking-widest uppercase text-rose-300/80">
                            공포 단계 (Dread)
                        </span>
                        <span className="text-sm text-white font-semibold">
                            {DREAD_BANDS[dreadBand].ko}
                            <span className="ml-1 text-xs text-slate-500">({DREAD_BANDS[dreadBand].en})</span>
                        </span>
                    </div>
                    <div className="grid grid-cols-6 gap-1">
                        {DREAD_BANDS.map(d => (
                            <button
                                key={d.id}
                                onClick={() => setDreadBand(d.id)}
                                className={`rounded-md px-1 py-1.5 text-[11px] sm:text-xs font-medium transition-all ${
                                    d.id === dreadBand
                                        ? `bg-gradient-to-r ${BAND_CLASS[d.id]} text-white shadow-md`
                                        : "bg-white/[0.03] text-slate-400 hover:bg-white/[0.08]"
                                }`}
                            >
                                <div className="truncate">{d.ko}</div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* 영역 요약 (5칸) */}
                <div className="grid grid-cols-5 gap-1.5 sm:gap-2">
                    <div className="rounded-xl border border-white/10 bg-white/[0.03] px-2 py-2 text-center">
                        <div className="text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-500">덱</div>
                        <div className="text-base font-bold text-white tabular-nums">{remainingInDeck}</div>
                    </div>
                    <div className="rounded-xl border border-rose-400/20 bg-rose-500/5 px-2 py-2 text-center">
                        <div className="text-[9px] sm:text-[10px] uppercase tracking-widest text-rose-300/70">현재</div>
                        <div className="text-base font-bold text-white tabular-nums">{current ? 1 : 0}</div>
                    </div>
                    <div className="rounded-xl border border-white/10 bg-white/[0.03] px-2 py-2 text-center">
                        <div className="text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-500">버린</div>
                        <div className="text-base font-bold text-white tabular-nums">{discardPile.length}</div>
                    </div>
                    <div className="rounded-xl border border-amber-400/20 bg-amber-500/5 px-2 py-2 text-center">
                        <div className="text-[9px] sm:text-[10px] uppercase tracking-widest text-amber-300/70">유지</div>
                        <div className="text-base font-bold text-white tabular-nums">{activePlay.length}</div>
                    </div>
                    <div className="rounded-xl border border-fuchsia-400/20 bg-fuchsia-500/5 px-2 py-2 text-center">
                        <div className="text-[9px] sm:text-[10px] uppercase tracking-widest text-fuchsia-300/70">미사용</div>
                        <div className="text-base font-bold text-white tabular-nums">{unusedPool.length}</div>
                    </div>
                </div>

                {/* 조작 */}
                <div className="flex items-stretch gap-2">
                    <button
                        onClick={handleDraw}
                        disabled={!canDraw}
                        className="flex-1 inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-rose-500 to-fuchsia-500 px-4 py-3 text-sm font-bold text-white shadow-lg shadow-rose-500/20 transition-opacity hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                        <Play className="w-4 h-4" />
                        {!isSessionActive
                            ? "셔플 & 뽑기"
                            : current
                                ? "현재 카드 처리 필요"
                                : "카드 뽑기"}
                    </button>
                    <button
                        onClick={handleUndo}
                        disabled={!current}
                        title="맨 위에 되돌리기 (예지 / Peek)"
                        className="inline-flex items-center justify-center rounded-xl bg-white/[0.04] px-3 py-3 text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                    >
                        <Undo2 className="w-4 h-4" />
                    </button>
                    <button
                        onClick={handleReshuffle}
                        disabled={!canReshuffle}
                        title={isSessionActive ? "남은 덱 + 버린 더미 섞기 (유지/미사용 유지)" : "새 덱 구성"}
                        className="inline-flex items-center justify-center rounded-xl bg-white/[0.04] px-3 py-3 text-slate-300 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                    >
                        <Shuffle className="w-4 h-4" />
                    </button>
                </div>

                {deckEmpty && (
                    <div className="rounded-xl border border-amber-400/30 bg-amber-500/10 px-4 py-2 text-xs text-amber-200">
                        덱이 소진되었습니다.{" "}
                        {discardPile.length > 0
                            ? '"다시 섞기"로 버린 더미를 덱으로 되돌릴 수 있어요. (유지/미사용은 보존됩니다)'
                            : "버린 더미도 비어있어 되돌릴 카드가 없습니다."}
                    </div>
                )}

                {/* 현재 카드 + 처리 버튼 */}
                {current ? (
                    <div className="flex flex-col gap-2">
                        <CardView card={current} highlightDread={dreadBand} />
                        <div className="grid grid-cols-3 gap-2">
                            <button
                                onClick={() => handleResolveCurrent("discard")}
                                className="inline-flex items-center justify-center gap-2 rounded-xl bg-slate-500/20 px-3 py-2.5 text-sm font-semibold text-slate-100 ring-1 ring-slate-400/30 hover:bg-slate-500/30"
                            >
                                <Trash2 className="w-4 h-4" />
                                버리기
                            </button>
                            <button
                                onClick={() => handleResolveCurrent("shuffle")}
                                className="inline-flex items-center justify-center gap-2 rounded-xl bg-indigo-500/20 px-3 py-2.5 text-sm font-semibold text-indigo-100 ring-1 ring-indigo-400/30 hover:bg-indigo-500/30"
                            >
                                <Shuffle className="w-4 h-4" />
                                덱에 섞기
                            </button>
                            <button
                                onClick={() => handleResolveCurrent("keep")}
                                className="inline-flex items-center justify-center gap-2 rounded-xl bg-amber-500/20 px-3 py-2.5 text-sm font-semibold text-amber-100 ring-1 ring-amber-400/30 hover:bg-amber-500/30"
                            >
                                <Bookmark className="w-4 h-4" />
                                유지
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="flex h-[30vh] flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/[0.02] text-center p-8">
                        <Shuffle className="w-8 h-8 text-slate-600 mb-3" />
                        <p className="text-sm text-slate-400">
                            {cardPool.length === 0
                                ? "덱 구성에서 세트를 하나 이상 선택하세요"
                                : targetDeckSize === 0
                                    ? "유형별 매수를 1 이상으로 설정하세요"
                                    : !isSessionActive
                                        ? '"셔플 & 뽑기"를 눌러 시작하세요'
                                        : '"카드 뽑기"로 다음 카드를 공개하세요'}
                        </p>
                    </div>
                )}

                {/* 유지 중 카드 */}
                {activePlay.length > 0 && (
                    <div className="rounded-2xl border border-amber-400/20 bg-amber-500/5 p-3">
                        <div className="mb-2 flex items-center justify-between">
                            <span className="text-xs tracking-widest uppercase text-amber-300/70 flex items-center gap-1.5">
                                <Bookmark className="w-3.5 h-3.5" /> 유지 중 ({activePlay.length})
                            </span>
                            <span className="text-[11px] text-amber-200/60">
                                지속 효과 — 조건 해제 시 처리
                            </span>
                        </div>
                        <div className="flex flex-col gap-1.5">
                            {activePlay.map((c, i) => (
                                <div
                                    key={`${c.setId}-${c.globalId}-${i}`}
                                    onClick={() => setViewingCard(c)}
                                    className="flex items-center justify-between gap-2 rounded-lg bg-black/20 px-3 py-2 ring-1 ring-amber-400/10 cursor-pointer hover:bg-black/30 transition-colors"
                                >
                                    <div className="min-w-0 flex-1">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[10px] font-mono text-amber-200/50 tabular-nums">
                                                #{String(c.globalId).padStart(3, "0")}
                                            </span>
                                            <span className="text-sm font-semibold text-white truncate">
                                                {c.card_ko}
                                            </span>
                                            <Eye className="w-3 h-3 text-amber-200/40 shrink-0" />
                                        </div>
                                        <div className="text-[10px] text-slate-500 truncate">
                                            {c.type_ko || c.type} · {c.setName_ko}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-1 shrink-0" onClick={e => e.stopPropagation()}>
                                        <button
                                            onClick={() => handleActivePlayAction(i, "discard")}
                                            title="버리기"
                                            className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-slate-500/15 text-slate-200 ring-1 ring-slate-400/20 hover:bg-slate-500/30"
                                        >
                                            <Trash2 className="w-3.5 h-3.5" />
                                        </button>
                                        <button
                                            onClick={() => handleActivePlayAction(i, "shuffle")}
                                            title="덱에 섞기"
                                            className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-indigo-500/15 text-indigo-200 ring-1 ring-indigo-400/20 hover:bg-indigo-500/30"
                                        >
                                            <Shuffle className="w-3.5 h-3.5" />
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* 버린 더미 목록 (discardPile 있을 때 항상 표시) */}
                {discardPile.length > 0 && (
                    <div className="rounded-2xl border border-slate-400/20 bg-slate-500/5 p-3">
                        <button
                            type="button"
                            onClick={() => setDiscardListOpen(o => !o)}
                            className="flex w-full items-center justify-between gap-2"
                        >
                            <span className="text-xs tracking-widest uppercase text-slate-400 flex items-center gap-1.5">
                                <Trash2 className="w-3.5 h-3.5" /> 버린 더미 목록 ({discardPile.length})
                            </span>
                            {discardListOpen
                                ? <ChevronUp className="w-3.5 h-3.5 text-slate-400" />
                                : <ChevronDown className="w-3.5 h-3.5 text-slate-400" />}
                        </button>
                        {discardListOpen && (
                            <div className="mt-2 flex flex-col gap-1.5 max-h-72 overflow-y-auto">
                                {discardPile.map((c, i) => i).reverse().map(origIdx => {
                                    const c = discardPile[origIdx];
                                    return (
                                        <button
                                            key={`${c.setId}-${c.globalId}-${origIdx}`}
                                            type="button"
                                            onClick={() => setViewingCard(c)}
                                            className="flex items-center justify-between gap-2 rounded-lg bg-black/20 px-3 py-2 ring-1 ring-white/5 text-left hover:bg-black/30 transition-colors"
                                        >
                                            <div className="min-w-0 flex-1">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] font-mono text-slate-500 tabular-nums">
                                                        #{String(c.globalId).padStart(3, "0")}
                                                    </span>
                                                    <span className="text-sm font-semibold text-slate-100 truncate">
                                                        {c.card_ko}
                                                    </span>
                                                    <Eye className="w-3 h-3 text-slate-500 shrink-0" />
                                                </div>
                                                <div className="text-[10px] text-slate-500 truncate">
                                                    {c.type_ko || c.type} · {c.setName_ko}
                                                </div>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}

                {/* 버린 더미 역추적 (current 없고 discardPile 있을 때) */}
                {!current && discardPile.length > 0 && (
                    <div className="rounded-2xl border border-slate-400/20 bg-slate-500/5 p-3">
                        <div className="mb-2 flex items-center justify-between">
                            <span className="text-xs tracking-widest uppercase text-slate-400 flex items-center gap-1.5">
                                <RotateCcw className="w-3.5 h-3.5" /> 버린 더미에서 가져오기
                            </span>
                            <span className="text-[11px] text-slate-500">총 {discardPile.length}장</span>
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            <button
                                onClick={() => recallFromDiscard(c => splitTypes(c.type).includes("Veteran"), "top")}
                                disabled={discardVeteranCount === 0}
                                className="rounded-lg bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                            >
                                Top 베테랑 <span className="text-slate-500">({discardVeteranCount})</span>
                            </button>
                            <button
                                onClick={() => recallFromDiscard(c => !splitTypes(c.type).includes("Veteran"), "top")}
                                disabled={discardNonVeteranCount === 0}
                                className="rounded-lg bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                            >
                                Top 非-베테랑 <span className="text-slate-500">({discardNonVeteranCount})</span>
                            </button>
                            <button
                                onClick={() => recallFromDiscard(c => splitTypes(c.type).includes("Revenant"), "random")}
                                disabled={discardRevenantCount === 0}
                                className="rounded-lg bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                            >
                                레븐넌트 랜덤 <span className="text-slate-500">({discardRevenantCount})</span>
                            </button>
                            <button
                                onClick={recallAllToDeck}
                                className="rounded-lg bg-indigo-500/15 px-3 py-1.5 text-xs text-indigo-100 ring-1 ring-indigo-400/20 hover:bg-indigo-500/25"
                            >
                                모두 덱으로 섞기
                            </button>
                        </div>
                    </div>
                )}

                {/* 연쇄 드로우 (current 없고 덱에 카드 있을 때) */}
                {!current && isSessionActive && eventDeck.length > 0 && typeList.length > 0 && (
                    <div className="rounded-2xl border border-cyan-400/20 bg-cyan-500/5 p-3">
                        <div className="mb-2 flex items-center justify-between">
                            <span className="text-xs tracking-widest uppercase text-cyan-300/70 flex items-center gap-1.5">
                                <FastForward className="w-3.5 h-3.5" /> 연쇄 드로우
                            </span>
                            <span className="text-[11px] text-cyan-200/50">
                                덱 {eventDeck.length}장 · 중간 카드는 자동 폐기
                            </span>
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            {typeList.map(t => {
                                const label = TYPE_KO_MAP[t] || t;
                                const cnt = eventDeck.filter(c => splitTypes(c.type).includes(t)).length;
                                return (
                                    <button
                                        key={t}
                                        onClick={() => chainDrawUntil(t)}
                                        disabled={cnt === 0}
                                        title={t}
                                        className="rounded-lg bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                                    >
                                        {label}까지 <span className="text-slate-500">({cnt})</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* 미사용 풀 추첨 (current 없고 unusedPool 있을 때) */}
                {!current && unusedPool.length > 0 && (
                    <div className="rounded-2xl border border-fuchsia-400/20 bg-fuchsia-500/5 p-3">
                        <div className="mb-2 flex items-center justify-between">
                            <span className="text-xs tracking-widest uppercase text-fuchsia-300/70 flex items-center gap-1.5">
                                <Sparkles className="w-3.5 h-3.5" /> 미사용 풀 추첨 ({unusedPool.length})
                            </span>
                            <span className="text-[11px] text-fuchsia-200/50">카드 효과로 호출</span>
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            <button
                                onClick={() => drawFromUnused(null)}
                                className="rounded-lg bg-fuchsia-500/20 px-3 py-1.5 text-xs text-fuchsia-100 ring-1 ring-fuchsia-400/30 hover:bg-fuchsia-500/30 font-semibold"
                            >
                                아무 유형 랜덤
                            </button>
                            {unusedTypeList.map(t => {
                                const label = TYPE_KO_MAP[t] || t;
                                const count = unusedByType[t] || 0;
                                return (
                                    <button
                                        key={t}
                                        onClick={() => drawFromUnused(t)}
                                        disabled={count === 0}
                                        className="rounded-lg bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 ring-1 ring-white/10 hover:bg-white/[0.08] disabled:opacity-40"
                                        title={t}
                                    >
                                        {label} <span className="text-slate-500">({count})</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* 이력 썸네일 */}
                {history.length > 0 && (
                    <div>
                        <div className="text-xs tracking-widest uppercase text-slate-500 mb-2">
                            이력 (최근 → 과거)
                        </div>
                        <div className="flex gap-2 overflow-x-auto pb-2">
                            {history.slice(-10).reverse().map((h, i) => {
                                const c = h.card;
                                const actionLabel = h.action === "discard" ? "버림"
                                    : h.action === "shuffle" ? "재셔플"
                                    : "유지";
                                const actionColor = h.action === "discard" ? "text-slate-400"
                                    : h.action === "shuffle" ? "text-indigo-300"
                                    : "text-amber-300";
                                return (
                                    <div
                                        key={`${c.setId}-${c.globalId}-${history.length - 1 - i}`}
                                        className="shrink-0 rounded-lg border border-white/10 bg-white/[0.02] px-3 py-2 min-w-[150px]"
                                    >
                                        <div className="flex items-center justify-between gap-2">
                                            <span className="text-[10px] font-mono text-slate-500">
                                                #{String(c.globalId).padStart(3, "0")}
                                            </span>
                                            <span className={`text-[9px] font-semibold ${actionColor}`}>
                                                {actionLabel}
                                            </span>
                                        </div>
                                        <div className="text-xs font-semibold text-white truncate">
                                            {c.card_ko}
                                        </div>
                                        <div className="text-[10px] text-slate-500 truncate">
                                            {c.setName_ko}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}
            </section>

            {/* 카드 상세 보기 모달 */}
            {viewingCard && (
                <div
                    role="dialog"
                    aria-modal="true"
                    onClick={() => setViewingCard(null)}
                    className="fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-black/80 p-4 backdrop-blur-sm sm:items-center"
                >
                    <div
                        onClick={e => e.stopPropagation()}
                        className="relative w-full max-w-md"
                    >
                        <button
                            type="button"
                            onClick={() => setViewingCard(null)}
                            aria-label="닫기"
                            className="absolute right-2 top-2 z-10 rounded-full bg-black/60 p-2 text-white backdrop-blur hover:bg-black/80"
                        >
                            <X className="w-4 h-4" />
                        </button>
                        <CardView card={viewingCard} highlightDread={dreadBand} />
                    </div>
                </div>
            )}
        </div>
    );
}
